import random
import itertools

def get_cost(p, n):
    a = [float('inf')] * n
    d = [float('-inf')] * n
    for t, match in enumerate(p, 1):
        for player in match:
            a[player] = min(a[player], t)
            d[player] = max(d[player], t)
    return sum(d[i] - a[i] + 1 for i in range(n))

def solve_small_fast(n):
    players = list(range(n))
    matches = list(itertools.combinations(players, 2))
    num_matches = len(matches)
    if num_matches < 2:
        return get_cost(matches, n)

    best_cost = float('inf')
    for _ in range(15): 
        current_p = list(matches)
        random.shuffle(current_p)
        current_cost = get_cost(current_p, n)

        for _ in range(20000):
            i, j = random.sample(range(num_matches), 2)
            current_p[i], current_p[j] = current_p[j], current_p[i]
            new_cost = get_cost(current_p, n)
            if new_cost < current_cost:
                current_cost = new_cost
            else:
                current_p[i], current_p[j] = current_p[j], current_p[i]
        best_cost = min(best_cost, current_cost)

    return best_cost

for n in range(2, 9):
    print(f"n={n}, cost={solve_small_fast(n)}")
